void quickSort(int array[], int u, int v){ if(u==v) return; int q = perno(array, u, v); if(u&lt;q) quickSort(array, u, q-1); if(q&lt;v) quickSort(array, q+1, v);}
int perno(int array[], int primo, int ultimo){ int i = primo; // Limite sinistro int j = ultimo+1; // Limite destro int pivot = array[primo]; // Elemento che cerchiamo while(i&lt;j){ // Cerchiamo un elemento da portare da sinistra a destra do i++; while(array[i]&lt;=pivot); // Cerchiamo un elemento da portare da destra a sinistra do j--; while(array[j]&gt;pivot); // Se abbiamo trovato entrambi, li scambiamo if(i&lt;j) scambiaInt(&amp;array[i], &amp;array[j]); } // Mettiamo il pivot al centro scambiaInt(&amp;array[primo], &amp;array[j]); return j;}

